function UNSAT_CERTIFICATE(n, k, m, q):
    S <- (n*q)^k - (n*(q-1))^k
    first_moment <- q^n * S^m
    num_formulas <- ((n*q)^k)^m
    if first_moment < num_formulas:
        return 'UNSAT-FORCED'
    else:
        return 'INCONCLUSIVE'

function CRITICAL_DENSITY(k, q):
    return -ln(q) / log(1 - ((q-1)/q)^k)

function SMALLEST_FORCED_M(n, k, q):
    log_entropy <- n*ln(q);  log_frac <- log(1 - ((q-1)/q)^k)
    hi <- 1
    while log_entropy + hi*log_frac >= 0: hi <- 2*hi
    lo <- 0
    while lo < hi:
        mid <- (lo+hi)//2
        if log_entropy + mid*log_frac < 0: hi <- mid
        else: lo <- mid+1
    return lo

